"use client"

import * as React from "react"
import { Select as SelectPrimitive } from "@base-ui/react/select"

import { cn } from "@/lib/utils"
import { ChevronDownIcon, CheckIcon, ChevronUpIcon } from "lucide-react"
import "../styles/brutalist.css"

const Select = SelectPrimitive.Root

function SelectGroup({ className, ...props }: SelectPrimitive.Group.Props) {
  return (
    <SelectPrimitive.Group
      data-slot="select-group"
      className={cn("scroll-my-1 p-1", className)}
      {...props}
    />
  )
}

function SelectValue({ className, ...props }: SelectPrimitive.Value.Props) {
  return (
    <SelectPrimitive.Value
      data-slot="select-value"
      className={cn("flex flex-1 text-left", className)}
      {...props}
    />
  )
}

function SelectTrigger({
  className,
  size = "default",
  children,
  ...props
}: SelectPrimitive.Trigger.Props & {
  size?: "sm" | "default"
}) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        "brut-input brut-focus flex w-fit items-center justify-between gap-2 bg-card py-2 pr-2.5 pl-3 text-sm font-bold whitespace-nowrap outline-none select-none disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive data-placeholder:text-muted-foreground data-[size=default]:h-10 data-[size=sm]:h-8 *:data-[slot=select-value]:line-clamp-1 *:data-[slot=select-value]:flex *:data-[slot=select-value]:items-center *:data-[slot=select-value]:gap-1.5 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon
        render={
          <ChevronDownIcon className="pointer-events-none size-4 text-muted-foreground" />
        }
      />
    </SelectPrimitive.Trigger>
  )
}

function SelectContent({
  className,
  children,
  side = "bottom",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  alignItemWithTrigger = true,
  ...props
}: SelectPrimitive.Popup.Props &
  Pick<
    SelectPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "alignItemWithTrigger"
  >) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
        className="isolate z-50"
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          data-align-trigger={alignItemWithTrigger}
          className={cn("brut-popover relative isolate z-50 max-h-(--available-height) w-(--anchor-width) min-w-40 origin-(--transform-origin) overflow-x-hidden overflow-y-auto bg-popover p-1 text-popover-foreground duration-100 data-[align-trigger=true]:animate-none data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95", className )}
          {...props}
        >
          <SelectScrollUpButton />
          <SelectPrimitive.List>{children}</SelectPrimitive.List>
          <SelectScrollDownButton />
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  )
}

function SelectLabel({
  className,
  ...props
}: SelectPrimitive.GroupLabel.Props) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn("px-2 py-1.5 text-xs font-black tracking-wider text-muted-foreground uppercase", className)}
      {...props}
    />
  )
}

function SelectItem({
  className,
  children,
  ...props
}: SelectPrimitive.Item.Props) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(
        "relative flex w-full cursor-default items-center gap-1.5 rounded-[calc(var(--radius)*0.65)] border-2 border-transparent py-2 pr-8 pl-2 text-sm font-bold outline-hidden select-none focus:border-border focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-2",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex flex-1 shrink-0 gap-2 whitespace-nowrap">
        {children}
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute right-2 flex size-4 items-center justify-center" />
        }
      >
        <CheckIcon className="pointer-events-none" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  )
}

function SelectSeparator({
  className,
  ...props
}: SelectPrimitive.Separator.Props) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("pointer-events-none -mx-1 my-1 h-[var(--brut-border)] bg-border", className)}
      {...props}
    />
  )
}

function SelectScrollUpButton({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollUpArrow>) {
  return (
    <SelectPrimitive.ScrollUpArrow
      data-slot="select-scroll-up-button"
      className={cn(
        "top-0 z-10 flex w-full cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <ChevronUpIcon
      />
    </SelectPrimitive.ScrollUpArrow>
  )
}

function SelectScrollDownButton({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollDownArrow>) {
  return (
    <SelectPrimitive.ScrollDownArrow
      data-slot="select-scroll-down-button"
      className={cn(
        "bottom-0 z-10 flex w-full cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <ChevronDownIcon
      />
    </SelectPrimitive.ScrollDownArrow>
  )
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
}

:root,
[data-brut-palette="paper"] {
  --background: oklch(0.985 0.004 95);
  --foreground: oklch(0.15 0.01 65);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.82 0.18 88);
  --primary-foreground: oklch(0.13 0.01 70);
  --secondary: oklch(0.88 0.105 210);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.94 0.018 90);
  --muted-foreground: oklch(0.38 0.02 65);
  --accent: oklch(0.72 0.2 20);
  --accent-foreground: oklch(0.99 0 0);
  --destructive: oklch(0.61 0.24 28);
  --border: oklch(0.15 0.01 65);
  --input: oklch(0.15 0.01 65);
  --ring: oklch(0.56 0.23 264);
  --brut-shadow-color: oklch(0.15 0.01 65);
  --brut-grid-color: oklch(0.15 0.01 65 / 9%);
}

:root {
  --chart-1: var(--primary);
  --chart-2: var(--secondary);
  --chart-3: var(--accent);
  --chart-4: var(--destructive);
  --chart-5: var(--muted-foreground);
  --sidebar: var(--card);
  --sidebar-foreground: var(--card-foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);
}

[data-brut-palette="signal"] {
  --background: oklch(0.91 0.16 96);
  --foreground: oklch(0.13 0.01 70);
  --card: oklch(0.985 0.025 96);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.025 96);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.15 0.01 70);
  --primary-foreground: oklch(0.93 0.17 96);
  --secondary: oklch(0.73 0.2 28);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.86 0.11 96);
  --muted-foreground: oklch(0.31 0.03 70);
  --accent: oklch(0.75 0.13 222);
  --accent-foreground: oklch(0.13 0.01 70);
  --destructive: oklch(0.55 0.24 28);
  --border: oklch(0.13 0.01 70);
  --input: oklch(0.13 0.01 70);
  --ring: oklch(0.55 0.24 28);
  --brut-shadow-color: oklch(0.13 0.01 70);
  --brut-grid-color: oklch(0.13 0.01 70 / 12%);
}

[data-brut-palette="sky"] {
  --background: oklch(0.92 0.055 235);
  --foreground: oklch(0.16 0.04 255);
  --card: oklch(0.98 0.018 230);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.018 230);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.52 0.2 255);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.88 0.16 92);
  --secondary-foreground: oklch(0.16 0.04 255);
  --muted: oklch(0.86 0.045 235);
  --muted-foreground: oklch(0.36 0.055 255);
  --accent: oklch(0.71 0.18 28);
  --accent-foreground: oklch(0.16 0.04 255);
  --destructive: oklch(0.56 0.24 27);
  --border: oklch(0.16 0.04 255);
  --input: oklch(0.16 0.04 255);
  --ring: oklch(0.67 0.2 28);
  --brut-shadow-color: oklch(0.16 0.04 255);
  --brut-grid-color: oklch(0.16 0.04 255 / 11%);
}

:root,
[data-brut-strength="solid"] {
  --brut-border: 2px;
  --brut-shadow-x: 4px;
  --brut-shadow-y: 4px;
  --brut-panel-shadow-x: 7px;
  --brut-panel-shadow-y: 7px;
  --brut-hover: -1px;
  --brut-press: 2px;
  --brut-weight: 700;
}

[data-brut-strength="soft"] {
  --brut-border: 1px;
  --brut-shadow-x: 2px;
  --brut-shadow-y: 2px;
  --brut-panel-shadow-x: 4px;
  --brut-panel-shadow-y: 4px;
  --brut-hover: -1px;
  --brut-press: 1px;
  --brut-weight: 600;
}

[data-brut-strength="loud"] {
  --brut-border: 3px;
  --brut-shadow-x: 6px;
  --brut-shadow-y: 6px;
  --brut-panel-shadow-x: 9px;
  --brut-panel-shadow-y: 9px;
  --brut-hover: -2px;
  --brut-press: 3px;
  --brut-weight: 800;
}

:root,
[data-brut-radius="sharp"] {
  --radius: 0rem;
}

[data-brut-radius="cut"] {
  --radius: 0.375rem;
}

[data-brut-radius="chunky"] {
  --radius: 0.875rem;
}

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 60%, transparent);
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    background-image:
      linear-gradient(var(--brut-grid-color) 1px, transparent 1px),
      linear-gradient(90deg, var(--brut-grid-color) 1px, transparent 1px);
    background-size: 28px 28px;
  }

  ::selection {
    background: var(--primary);
    color: var(--primary-foreground);
  }
}

@layer components {
  .brut-panel {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-panel-shadow-x) var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-surface {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-control {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: var(--brut-weight);
    transition: transform 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
  }

  .brut-control:hover:not(:disabled, [data-disabled]) {
    transform: translate(var(--brut-hover), var(--brut-hover));
    box-shadow: calc(var(--brut-shadow-x) - var(--brut-hover)) calc(var(--brut-shadow-y) - var(--brut-hover)) 0 var(--brut-shadow-color);
  }

  .brut-control:active:not(:disabled, [data-disabled]),
  .brut-control[data-pressed] {
    transform: translate(var(--brut-press), var(--brut-press));
    box-shadow: 0 0 0 var(--brut-shadow-color);
  }

  .brut-quiet {
    border: var(--brut-border) solid transparent;
    border-radius: var(--radius);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-quiet:hover {
    border-color: var(--border);
    background: var(--muted);
  }

  .brut-focus:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 3px;
  }

  .brut-input {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input-group:focus-within {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-input-group:has([aria-invalid="true"]):focus-within {
    outline-color: var(--destructive);
  }

  .brut-otp-group:has([data-active="true"]) {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-otp-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-otp-group:has([aria-invalid="true"]):has([data-active="true"]) {
    outline-color: var(--destructive);
  }

  .brut-chip {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.75);
    box-shadow: none;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .brut-toggle {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-kbd {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.6);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-item {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: none;
  }

  .brut-accordion-item:not(:last-child) {
    border-bottom: var(--brut-border) solid var(--border);
    box-shadow: none;
  }

  .brut-check {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.5);
    background: var(--card);
    box-shadow: 2px 2px 0 var(--brut-shadow-color);
  }

  .brut-avatar {
    border: var(--brut-border) solid var(--border);
    background: var(--card);
    box-shadow: calc(var(--brut-border) + 1px) calc(var(--brut-border) + 1px) 0 var(--brut-shadow-color);
  }

  .brut-separator {
    background: var(--border);
  }

  .brut-dialog {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-panel-shadow-x) var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-questionnaire-choice {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
  }

  .brut-sheet[data-side="right"] {
    border-left: var(--brut-border) solid var(--border);
    border-radius: var(--radius) 0 0 var(--radius);
    box-shadow: calc(0px - var(--brut-panel-shadow-x)) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="left"] {
    border-right: var(--brut-border) solid var(--border);
    border-radius: 0 var(--radius) var(--radius) 0;
    box-shadow: var(--brut-panel-shadow-x) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="bottom"] {
    border-top: var(--brut-border) solid var(--border);
    border-radius: var(--radius) var(--radius) 0 0;
    box-shadow: 0 calc(0px - var(--brut-panel-shadow-y)) 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="top"] {
    border-bottom: var(--brut-border) solid var(--border);
    border-radius: 0 0 var(--radius) var(--radius);
    box-shadow: 0 var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="down"] {
    border-top: var(--brut-border) solid var(--border);
    border-radius: var(--radius) var(--radius) 0 0;
    box-shadow: 0 calc(0px - var(--brut-panel-shadow-y)) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="up"] {
    border-bottom: var(--brut-border) solid var(--border);
    border-radius: 0 0 var(--radius) var(--radius);
    box-shadow: 0 var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="left"] {
    border-right: var(--brut-border) solid var(--border);
    border-radius: 0 var(--radius) var(--radius) 0;
    box-shadow: var(--brut-panel-shadow-x) 0 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="right"] {
    border-left: var(--brut-border) solid var(--border);
    border-radius: var(--radius) 0 0 var(--radius);
    box-shadow: calc(0px - var(--brut-panel-shadow-x)) 0 0 var(--brut-shadow-color);
  }

  .brut-popover {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-switch {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: 3px 3px 0 var(--brut-shadow-color);
  }

  .brut-switch-thumb {
    border-radius: calc(var(--radius) * 0.75);
  }

  .brut-progress {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    background: var(--card);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
